function formatContinental(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return String(n);
  const sign = x < 0 ? "-" : "";
  const a = Math.abs(x);
  const parts = a.toFixed(2).split(".");
  const grouped = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return sign + grouped + "," + parts[1];
}
function formatAu(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return "—";
  const sign = x < 0 ? "-" : "";
  const a = Math.abs(x);
  if (a >= 1e6) return sign + formatContinental(a / 1e6) + " million €Au";
  return sign + formatContinental(a) + " €Au";
}
async function loadJson(url) {
  const r = await fetch(url, { cf: { cacheTtl: 120, cacheEverything: true } });
  if (!r.ok) throw new Error(url + " " + r.status);
  return r.json();
}
const AURUM_LIVE_WIDGET = "<style>\n.livebox{max-width:28rem;margin:2.4rem auto 1.2rem;padding:1.1rem 1.2rem;border:1px solid rgba(0,0,0,.15)}\n.live-h{text-align:center;font-weight:600;letter-spacing:.02em;margin-bottom:.15rem}\n.live-sub{text-align:center;font-size:.85rem;color:#444;margin-bottom:1rem}\n.live-eur{text-align:center;margin:0 0 1rem}\n.live-eur .eq{font-size:1.55rem;font-weight:650;letter-spacing:.01em}\n.live-row{display:grid;grid-template-columns:3.2rem 1fr auto;gap:.5rem;align-items:center;padding:.12rem 0}\n.px{text-align:right}\n.ch{min-width:4.2rem;text-align:right;padding:0 .35rem;border-radius:2px}\n.ch.up{color:#0a6b2d;background:#e8f6ec}\n.ch.down{color:#8b1e1e;background:#f8eaea}\n</style>\n<div id=\"eau-live\" class=\"livebox\" aria-live=\"polite\">\n  <div class=\"live-h\">Settlement Values \u2022 Yearly Volatility</div>\n  <div class=\"live-sub\">\u20acAu is the invariant. The fiat figures are the variable settlement prices of one unit, against the same month a year earlier.</div>\n  <div class=\"live-eur\" id=\"eau-live-eur\">Loading settlement quotation\u2026</div>\n  <div id=\"eau-live-rows\"></div>\n</div>\n<script>\n(function(){\n  function fmt(n){\n    const x = Number(n);\n    if (!Number.isFinite(x)) return \"\u2014\";\n    const sign = x < 0 ? \"-\" : \"\";\n    const a = Math.abs(x);\n    const d = a >= 100 ? 2 : (a >= 1 ? 2 : 4);\n    const parts = a.toFixed(d).split(\".\");\n    const grouped = parts[0].replace(/\\B(?=(\\d{3})+(?!\\d))/g, \".\");\n    return sign + grouped + \",\" + parts[1];\n  }\n  function pct(n){\n    if (n == null || !Number.isFinite(Number(n))) return \"\";\n    const x = Number(n);\n    const sign = x > 0 ? \"+\" : \"\";\n    return sign + x.toFixed(1).replace(\".\", \",\") + \"%\";\n  }\n  fetch(\"/aurum-euro/api/v1/live-price\").then(r => r.json()).then(d => {\n    const eurBox = document.getElementById(\"eau-live-eur\");\n    const box = document.getElementById(\"eau-live-rows\");\n    if (!d || !d.rows) {\n      if (eurBox) eurBox.textContent = \"Settlement quotation unavailable.\";\n      return;\n    }\n    const eur = d.rows.find(r => r.code === \"EUR\");\n    const others = d.rows.filter(r => r.code !== \"EUR\").sort((a,b) => Number(a.per_eau) - Number(b.per_eau));\n    if (eur && eurBox) {\n      const ch = eur.change_pct;\n      const cls = ch == null ? \"\" : (ch >= 0 ? \"up\" : \"down\");\n      eurBox.innerHTML = '<div class=\"eq\">1 \u20acAu = '+fmt(eur.per_eau)+' EUR</div><div class=\"ch '+cls+'\" style=\"display:inline-block;margin-top:.35rem\">'+pct(ch)+'</div>';\n    }\n    if (box) box.innerHTML = others.map(row => {\n      const ch = row.change_pct;\n      const cls = ch == null ? \"\" : (ch >= 0 ? \"up\" : \"down\");\n      return '<div class=\"live-row\"><span class=\"ccy\">'+row.code+'</span><span class=\"px\">'+fmt(row.per_eau)+'</span><span class=\"ch '+cls+'\">'+pct(ch)+'</span></div>';\n    }).join(\"\");\n  }).catch(() => {\n    const eurBox = document.getElementById(\"eau-live-eur\");\n    if (eurBox) eurBox.textContent = \"Settlement quotation unavailable.\";\n  });\n})();\n</script>";
function annualisedPct(cur, prev, years) {
  if (cur == null || prev == null || !prev || !years || years <= 0) return null;
  return ((cur - prev) / Math.abs(prev) * 100) / years;
}
function yearOf(period) {
  const y = parseInt(String(period || "").slice(0, 4), 10);
  return Number.isFinite(y) ? y : null;
}
function lagYears(period, nowYear) {
  const y = yearOf(period);
  if (!y) return 0;
  return Math.max(0, (nowYear || new Date().getUTCFullYear()) - y);
}
function starMark(lag) {
  if (!lag || lag <= 0) return "";
  return "*".repeat(lag);
}
function metricAu(o) {
  if (!o) return null;
  if (o.equity_au != null) return Number(o.equity_au);
  if (o.assets_au != null) return Number(o.assets_au);
  if (o.revenue_au != null) return Number(o.revenue_au);
  return null;
}
function fmtPct(n) {
  if (n == null || !Number.isFinite(Number(n))) return "—";
  const x = Number(n);
  const sign = x > 0 ? "+" : "";
  return sign + x.toFixed(1).replace(".", ",") + "% / year";
}
